def backfill_reference_id(apps, schema_editor):
    """Give every existing request its own RFI-<year>-<pk>.

    Copied verbatim from 0005. The field is added non-unique, backfilled here,
    then tightened to unique — adding it as unique in one step collides the
    instant there is more than one existing row, and this deployment has
    dozens.
    """
    VendorRequest = apps.get_model("vendorlink", "VendorRequest")
    for vendor_request in VendorRequest.objects.all().only("pk", "created_at"):
        year = vendor_request.created_at.year if vendor_request.created_at else 2026
        VendorRequest.objects.filter(pk=vendor_request.pk).update(
            reference_id=f"RFI-{year}-{vendor_request.pk:06d}"
        )


