def keep_one_selection_per_request(apps, schema_editor):
    """Heal requests carrying more than one selected bid.

    Copied verbatim from 0008. Selection used to be cleared per vendor, so
    picking a bid from a second vendor left the first selected too and the
    screen read "2 chosen" on a request that can only go to one vendor.

    Which one survives: the awarded bid if the request has an award (an award
    is a commitment the vendor was already mailed about, so the selection has
    to agree with it), otherwise the most recently submitted.
    """
    from django.db.models import Count, Q

    VendorBid = apps.get_model("vendorlink", "VendorBid")
    BidAward = apps.get_model("vendorlink", "BidAward")

    offenders = (
        VendorBid.objects.values("vendor_request_id")
        .annotate(selected=Count("pk", filter=Q(is_selected=True)))
        .filter(selected__gt=1)
        .values_list("vendor_request_id", flat=True)
    )

    for request_id in list(offenders):
        selected = list(
            VendorBid.objects.filter(vendor_request_id=request_id, is_selected=True)
            .order_by("submitted_at", "pk")
        )
        awarded_bid_ids = set(
            BidAward.objects.filter(vendor_request_id=request_id)
            .values_list("bid_id", flat=True)
        )

        keep = next((bid for bid in selected if bid.pk in awarded_bid_ids), None)
        if keep is None:
            keep = selected[-1]

        VendorBid.objects.filter(
            vendor_request_id=request_id, is_selected=True,
        ).exclude(pk=keep.pk).update(is_selected=False)


