from vendorlink.constants import DEFAULT_CAPABILITIES

CODES = [code for code, _label, _icon in DEFAULT_CAPABILITIES]


def seed_and_migrate(apps, schema_editor):
    Capability = apps.get_model("vendorlink", "Capability")
    Vendor = apps.get_model("vendorlink", "Vendor")
    VendorRegistration = apps.get_model("vendorlink", "VendorRegistration")

    rows = {}
    for index, (code, label, icon) in enumerate(DEFAULT_CAPABILITIES):
        rows[code], _ = Capability.objects.get_or_create(
            code=code,
            defaults={"label": label, "icon": icon, "sort_order": (index + 1) * 10},
        )

    for model in (Vendor, VendorRegistration):
        for holder in model.objects.all().iterator():
            held = [rows[code] for code in CODES if getattr(holder, code, False)]
            if held:
                holder.capabilities.set(held)


def unmigrate(apps, schema_editor):
    """Write the links back into the boolean columns.

    The Capability rows are left in place: 0002 drops the table on its own way
    back, and deleting them here would break that migration's own reverse.
    """
    Vendor = apps.get_model("vendorlink", "Vendor")
    VendorRegistration = apps.get_model("vendorlink", "VendorRegistration")

    for model in (Vendor, VendorRegistration):
        for holder in model.objects.all().iterator():
            held = set(holder.capabilities.values_list("code", flat=True))
            for code in CODES:
                setattr(holder, code, code in held)
            holder.save(update_fields=CODES)


