def _add_missing_columns(apps, schema_editor):
    """Add each column, but only where it is not already there.

    A database migrated against smith's re-squash ALREADY has all three: the
    re-squashed 0001 carried them, which is the whole reason they were pulled
    out into this migration. Running a plain AddField against such a database
    fails outright —

        ProgrammingError: column "source" of relation
        "vendorlink_gptmessage" already exists

    — and that is not a hypothetical: it is what the running dev database did.
    A fresh database has none of them and needs all three. Neither case is
    wrong, so the migration asks rather than assumes, and both converge on the
    same schema without anyone having to --fake anything by hand.

    Written with the DEFAULT then dropped, which is what Django's own AddField
    does for a non-null column on a populated table.
    """
    connection = schema_editor.connection
    with connection.cursor() as cursor:
        for table, column, column_type in _COLUMNS:
            cursor.execute(
                "SELECT 1 FROM information_schema.columns "
                "WHERE table_schema = current_schema() "
                "AND table_name = %s AND column_name = %s",
                [table, column],
            )
            if cursor.fetchone():
                continue
            cursor.execute(
                f'ALTER TABLE "{table}" '
                f'ADD COLUMN "{column}" {column_type} NOT NULL DEFAULT \'\''
            )
            cursor.execute(f'ALTER TABLE "{table}" ALTER COLUMN "{column}" DROP DEFAULT')


def _drop_columns(apps, schema_editor):
    """Reverse: drop them where present, matching what AddField would undo."""
    connection = schema_editor.connection
    with connection.cursor() as cursor:
        for table, column, _type in _COLUMNS:
            cursor.execute(f'ALTER TABLE "{table}" DROP COLUMN IF EXISTS "{column}"')


